<?php
defined('ABSPATH') || exit;

$wradmin_settings = new WRADMIN_Settings();
$wradmin_pricing = WRADMIN_Pricing::all_for_js();
$wradmin_schemas = WRADMIN_REST_API::build_registry()->get_schemas();
$wradmin_disabled = $wradmin_settings->get_disabled_tools();
// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Read-only wizard stage.
$wradmin_step = isset($_GET['step']) ? sanitize_key(wp_unslash($_GET['step'])) : 'welcome';
if (!in_array($wradmin_step, ['welcome', 'try', 'done'], true)) {
    $wradmin_step = 'welcome';
}
$wradmin_groups = [
    'site' => ['label' => __('Site & navigation', 'william-research-admin-agent'), 'tools' => []],
    'content' => ['label' => __('Posts & media', 'william-research-admin-agent'), 'tools' => []],
    'store' => ['label' => __('Store & commerce', 'william-research-admin-agent'), 'tools' => []],
    'security' => ['label' => __('Security', 'william-research-admin-agent'), 'tools' => []],
    'other' => ['label' => __('Other abilities', 'william-research-admin-agent'), 'tools' => []],
];
foreach ($wradmin_schemas as $wradmin_schema) {
    $wradmin_name = $wradmin_schema['name'];
    $wradmin_group = 'site';
    if (preg_match('/post|image|icon|rss|media|pexels/', $wradmin_name)) {
        $wradmin_group = 'content';
    } elseif (preg_match('/woocommerce|product|order|coupon/', $wradmin_name)) {
        $wradmin_group = 'store';
    } elseif (preg_match('/wordfence|security|harden/', $wradmin_name)) {
        $wradmin_group = 'security';
    } elseif (!preg_match('/settings|plugin|theme|user|navigate/', $wradmin_name)) {
        $wradmin_group = 'other';
    }
    $wradmin_groups[$wradmin_group]['tools'][] = $wradmin_schema;
}
?>
