                <div class="wradmin-setup-actions"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="wradmin_setup_finish"><?php wp_nonce_field('wradmin_setup_finish'); ?><button type="submit" class="button button-primary button-hero"><?php esc_html_e('Finish setup', 'william-research-admin-agent'); ?></button></form><button type="button" class="button" id="wradmin-open-bot"><?php esc_html_e('Try a chat', 'william-research-admin-agent'); ?></button><a class="button" href="<?php echo esc_url(WRADMIN_Onboarding::url()); ?>"><?php esc_html_e('Back to choices', 'william-research-admin-agent'); ?></a></div>
